<?php
/**
 * Simple test script to verify SEO tags are being output correctly
 * 
 * This script simulates a WordPress environment to test if the SEO tags
 * are properly generated by the plugin.
 */

// Simulate WordPress functions
if (!function_exists('get_bloginfo')) {
    function get_bloginfo($show) {
        $info = array(
            'name' => 'Test Site',
            'description' => 'Test site description',
            'url' => 'https://example.com',
            'language' => 'en-US'
        );
        return isset($info[$show]) ? $info[$show] : '';
    }
}

if (!function_exists('home_url')) {
    function home_url($path = '') {
        return 'https://example.com' . $path;
    }
}

if (!function_exists('esc_html')) {
    function esc_html($text) {
        return htmlspecialchars($text, ENT_QUOTES, 'UTF-8');
    }
}

if (!function_exists('esc_attr')) {
    function esc_attr($text) {
        return htmlspecialchars($text, ENT_QUOTES, 'UTF-8');
    }
}

if (!function_exists('esc_url')) {
    function esc_url($url) {
        return htmlspecialchars($url, ENT_QUOTES, 'UTF-8');
    }
}

if (!function_exists('wp_trim_words')) {
    function wp_trim_words($text, $num_words = 55, $more = null) {
        $words = explode(' ', $text);
        if (count($words) > $num_words) {
            $words = array_slice($words, 0, $num_words);
            $text = implode(' ', $words);
            $text .= $more ? $more : '...';
        }
        return $text;
    }
}

if (!function_exists('get_locale')) {
    function get_locale() {
        return 'en_US';
    }
}

// Mock WordPress post object
class MockPost {
    public $ID = 1;
    public $post_title = 'Test Post Title';
    public $post_content = 'This is a test post content with enough words to generate a proper meta description. It should be long enough to test the trimming functionality.';
    public $post_excerpt = 'This is a test post excerpt.';
    public $post_author = 1;
    public $post_date = '2023-01-01 00:00:00';
    public $post_modified = '2023-01-01 00:00:00';
    public $post_type = 'post';
}

// Mock WordPress query conditions
function is_home() { return false; }
function is_front_page() { return false; }
function is_singular() { return true; }
function is_page() { return false; }
function is_single() { return true; }
function is_category() { return false; }
function is_tag() { return false; }
function is_tax() { return false; }
function is_author() { return false; }
function is_search() { return false; }
function is_404() { return false; }

function get_the_title($post) {
    return $post->post_title;
}

function get_permalink($post_id) {
    return 'https://example.com/test-post-' . $post_id;
}

function strip_tags($text) {
    return preg_replace('/<[^>]*>/', '', $text);
}

function strip_shortcodes($text) {
    return $text;
}

// Test the SEO meta tag output
echo "<h1>SEO Tags Test</h1>\n";

// Simulate the output_meta_tags function
function test_output_meta_tags() {
    global $post;
    $post = new MockPost();
    
    $title = '';
    $description = '';
    $keywords = '';
    
    // Handle different page types
    if (is_home() || is_front_page()) {
        // Homepage
        $title = get_bloginfo('name');
        $site_description = get_bloginfo('description');
        if (!empty($site_description)) {
            $title .= ' | ' . $site_description;
        }
        $description = get_bloginfo('description');
    } elseif (is_singular()) {
        // Singular posts/pages
        $title = get_the_title($post) . ' | ' . get_bloginfo('name');
        $description = !empty($post->post_excerpt) ? $post->post_excerpt : $post->post_content;
        $description = strip_tags($description);
        $description = strip_shortcodes($description);
        $description = wp_trim_words($description, 30, '...');
    }
    
    // Output meta tags with proper escaping
    echo "<h2>Basic Meta Tags</h2>\n";
    if (!empty($title)) {
        echo '<title>' . esc_html($title) . '</title>' . "\n";
    }
    
    if (!empty($description)) {
        echo '<meta name="description" content="' . esc_attr($description) . '">' . "\n";
    }
    
    if (!empty($keywords)) {
        echo '<meta name="keywords" content="' . esc_attr($keywords) . '">' . "\n";
    }
}

// Test the Open Graph tags output
function test_output_open_graph_tags() {
    global $post;
    $post = new MockPost();
    
    $title = '';
    $description = '';
    $image = '';
    $url = '';
    $type = 'website';
    
    // Handle different page types
    if (is_home() || is_front_page()) {
        // Homepage
        $title = get_bloginfo('name');
        $site_description = get_bloginfo('description');
        if (!empty($site_description)) {
            $title .= ' | ' . $site_description;
        }
        $description = get_bloginfo('description');
        $url = home_url('/');
    } elseif (is_singular()) {
        // Singular posts/pages
        $title = get_the_title($post) . ' | ' . get_bloginfo('name');
        $description = !empty($post->post_excerpt) ? $post->post_excerpt : $post->post_content;
        $description = strip_tags($description);
        $description = strip_shortcodes($description);
        $description = wp_trim_words($description, 30, '...');
        $url = get_permalink($post->ID);
        $type = is_page() ? 'website' : 'article';
    }
    
    $site_name = get_bloginfo('name');
    
    echo "<h2>Open Graph Tags</h2>\n";
    echo '<meta property="og:locale" content="' . esc_attr(get_locale()) . '">' . "\n";
    echo '<meta property="og:title" content="' . esc_attr($title) . '">' . "\n";
    
    if (!empty($description)) {
        echo '<meta property="og:description" content="' . esc_attr($description) . '">' . "\n";
    }
    
    if (!empty($url)) {
        echo '<meta property="og:url" content="' . esc_url($url) . '">' . "\n";
    }
    
    echo '<meta property="og:site_name" content="' . esc_attr($site_name) . '">' . "\n";
    echo '<meta property="og:type" content="' . esc_attr($type) . '">' . "\n";
}

// Test the Twitter Card tags output
function test_output_twitter_card_tags() {
    global $post;
    $post = new MockPost();
    
    $title = '';
    $description = '';
    $image = '';
    $url = '';
    
    // Handle different page types
    if (is_home() || is_front_page()) {
        // Homepage
        $title = get_bloginfo('name');
        $site_description = get_bloginfo('description');
        if (!empty($site_description)) {
            $title .= ' | ' . $site_description;
        }
        $description = get_bloginfo('description');
        $url = home_url('/');
    } elseif (is_singular()) {
        // Singular posts/pages
        $title = get_the_title($post) . ' | ' . get_bloginfo('name');
        $description = !empty($post->post_excerpt) ? $post->post_excerpt : $post->post_content;
        $description = strip_tags($description);
        $description = strip_shortcodes($description);
        $description = wp_trim_words($description, 30, '...');
        $url = get_permalink($post->ID);
    }
    
    // Determine card type based on image availability
    $card_type = !empty($image) ? 'summary_large_image' : 'summary';
    
    echo "<h2>Twitter Card Tags</h2>\n";
    echo '<meta name="twitter:card" content="' . esc_attr($card_type) . '">' . "\n";
    echo '<meta name="twitter:title" content="' . esc_attr($title) . '">' . "\n";
    
    if (!empty($description)) {
        echo '<meta name="twitter:description" content="' . esc_attr($description) . '">' . "\n";
    }
    
    if (!empty($url)) {
        echo '<meta name="twitter:url" content="' . esc_url($url) . '">' . "\n";
    }
}

// Test the canonical URL output
function test_output_canonical_url() {
    global $post;
    $post = new MockPost();
    
    $canonical_url = '';
    
    if (is_singular()) {
        $canonical_url = get_permalink($post->ID);
    } elseif (is_home() || is_front_page()) {
        $canonical_url = home_url('/');
    }
    
    echo "<h2>Canonical URL</h2>\n";
    if (!empty($canonical_url)) {
        echo '<link rel="canonical" href="' . esc_url($canonical_url) . '">' . "\n";
    }
}

// Test the robots meta tag output
function test_output_robots_meta() {
    $robots = array('index', 'follow');
    
    echo "<h2>Robots Meta Tag</h2>\n";
    if (!empty($robots)) {
        echo '<meta name="robots" content="' . esc_attr(implode(',', $robots)) . '">' . "\n";
    }
}

// Run all tests
echo "<div style='font-family: monospace; white-space: pre;'>\n";
test_output_meta_tags();
test_output_open_graph_tags();
test_output_twitter_card_tags();
test_output_canonical_url();
test_output_robots_meta();
echo "</div>\n";

echo "<h2>Test Complete</h2>\n";
echo "<p>If you can see the SEO tags above, the fix is working correctly.</p>\n";